import unittest
from flask import Flask, jsonify
from flask.testing import FlaskClient

# Define a sample Flask application for testing
app = Flask(__name__)

@app.route('/protected', methods=['GET'])
def protected():
    return jsonify({'message': 'This is a protected endpoint.'}), 200

class TestUnauthenticatedAccess(unittest.TestCase):
    def setUp(self):
        self.app: FlaskClient = app.test_client()

    def test_unauthenticated_access_to_protected_endpoint(self):
        response = self.app.get('/protected')
        self.assertEqual(response.status_code, 401)  # Expecting Unauthorized access
        self.assertIn(b'Authentication required', response.data)  # Example message

if __name__ == '__main__':
    unittest.main()

